sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-qa h2 { margin: 0 0 12px; font-size: 22px; color: var(--ink); }

.wrm-qa-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.wrm-qa-card {
  display: block;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-soft);
  padding: 16px 18px;
  text-decoration: none;
}
.wrm-qa-card:hover {
  border-color: var(--clay);
  text-decoration: none;
}
.wrm-qa-card .t { display: block; font-size: 15px; color: var(--ink); margin-bottom: 3px; }
.wrm-qa-card .s { display: block; font-size: 12px; color: var(--ink-3); }
